-- TCF-CE-1 #3 Lecture TCF : horaires et consignes (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce10', 'practice', 'Lecture TCF : horaires et consignes', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• annulé (participe) : bị huỷ\n• les voies (nom féminin pluriel) : đường ray\n• le passage souterrain : lối đi ngầm\n• les soldes : đợt giảm giá\n• le ramassage : việc thu gom","explications":"• Biển giờ mở cửa: đọc đúng dòng của ngày được hỏi.\n• Hai mốc thời gian gần nhau (mardi soir, mercredi matin): xem mốc nào gắn với hành động được hỏi.","isPremium":true,"price":19000,"kyNang":"TCF-CE-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-16T10:00:09.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce10q01', 'lo51tcfce10', 1, 'qcm', 'Quand peut-on aller à la poste le samedi ?', '{"doc":"<p><strong>BUREAU DE POSTE</strong></p><p>Lundi au vendredi : 9 h à 18 h</p><p>Samedi : 9 h à 12 h</p><p>Dimanche : fermé</p>","options":["L''après-midi, après le déjeuner.","Jamais, la poste est fermée le samedi.","Le matin seulement.","Toute la journée, de 9 h à 18 h."]}'::jsonb, '{"answer":2}'::jsonb, 'Biển ghi « Samedi : 9 h à 12 h »: chỉ buổi sáng.'),
  ('lo51tcfce10q02', 'lo51tcfce10', 2, 'qcm', 'Pourquoi le cours est-il annulé ?', '{"doc":"<p>Chère Madame,</p><p>Le cours de piano de Lina est annulé mercredi. Je suis malade. Le prochain cours aura lieu mercredi 21.</p><p>Cordialement, Marc Dupuis</p>","options":["Le piano doit être réparé.","Lina est malade ce mercredi-là.","La salle de musique est fermée.","Le professeur est malade."]}'::jsonb, '{"answer":3}'::jsonb, 'Thầy giáo viết « Je suis malade ».'),
  ('lo51tcfce10q03', 'lo51tcfce10', 3, 'qcm', 'Que doivent faire les voyageurs ?', '{"doc":"<p><strong>TRAIN EN GARE</strong></p><p>Pour votre sécurité, ne traversez pas les voies.</p><p>Utilisez le passage souterrain.</p>","options":["Passer sous les voies.","Attendre le train sur le quai d''en face.","Monter dans le premier wagon.","Traverser les voies avec prudence."]}'::jsonb, '{"answer":0}'::jsonb, 'Biển dặn « Utilisez le passage souterrain »: đi lối ngầm, không băng qua đường ray.'),
  ('lo51tcfce10q04', 'lo51tcfce10', 4, 'qcm', 'Que propose Tom ?', '{"doc":"<p>Salut Inès,</p><p>Je suis à la bibliothèque jusqu''à 17 h. Rendez-vous au café en face après ? J''ai ton livre.</p><p>Tom</p>","options":["D''aller ensemble à la bibliothèque.","D''acheter un nouveau livre pour Inès.","D''étudier chez Inès ce soir.","De se retrouver au café."]}'::jsonb, '{"answer":3}'::jsonb, 'Tom hỏi « Rendez-vous au café en face après ? ».'),
  ('lo51tcfce10q05', 'lo51tcfce10', 5, 'qcm', 'Quel article a la plus grande réduction ?', '{"doc":"<p><strong>SOLDES</strong></p><p>-30 % sur toutes les chaussures.</p><p>-50 % sur les manteaux d''hiver.</p><p>Offre valable jusqu''au 31 janvier.</p>","options":["Tous les articles du magasin.","Les manteaux.","Les chaussures.","Les vêtements d''été."]}'::jsonb, '{"answer":1}'::jsonb, 'Áo khoác giảm « -50 % », giày chỉ « -30 % ».'),
  ('lo51tcfce10q06', 'lo51tcfce10', 6, 'qcm', 'Quand faut-il sortir les poubelles ?', '{"doc":"<p><strong>Résidence Les Érables</strong></p><p>Les poubelles doivent être sorties le mardi soir.</p><p>Le ramassage a lieu le mercredi matin.</p>","options":["Le mercredi matin, avant le ramassage.","Le mardi soir.","Le mercredi soir.","Le mardi matin."]}'::jsonb, '{"answer":1}'::jsonb, 'Thông báo ghi « sorties le mardi soir ». Thứ Tư sáng là giờ xe rác đến lấy.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-1 #4 Lecture TCF : petites annonces (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce11', 'practice', 'Lecture TCF : petites annonces', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• meublé (adjectif) : có sẵn đồ đạc\n• charges comprises : đã gồm phí\n• à domicile : tại nhà\n• une récompense : phần thưởng\n• un vide-grenier : chợ đồ cũ\n• le covoiturage : đi chung xe","explications":"• Rao vặt có nhiều con số: đánh dấu xem số nào là giá, số nào là ngày, số nào là số lượng.\n• « comprises » (đã gồm) và « en plus » (cộng thêm) đổi hẳn giá phải trả.","isPremium":true,"price":19000,"kyNang":"TCF-CE-1","vong":"on","thuTu":4}'::jsonb, '2026-11-16T10:00:10.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce11q01', 'lo51tcfce11', 1, 'qcm', 'Combien coûte le studio par mois avec les charges ?', '{"doc":"<p><strong>À LOUER</strong></p><p>Studio meublé, 25 m², centre-ville.</p><p>450 € par mois, charges comprises.</p><p>Libre le 1er mars.</p>","options":["450 €.","450 € sans les charges.","Un peu plus de 450 €.","25 € de charges en plus."]}'::jsonb, '{"answer":0}'::jsonb, 'Quảng cáo ghi « 450 € par mois, charges comprises »: đã gồm phí.'),
  ('lo51tcfce11q02', 'lo51tcfce11', 2, 'qcm', 'Quelle condition est demandée ?', '{"doc":"<p><strong>Cherche baby-sitter</strong></p><p>Pour deux enfants (4 et 7 ans), le mercredi après-midi.</p><p>Expérience demandée. Non-fumeur.</p><p>Appeler Mme Roux le soir.</p>","options":["Être libre tous les après-midi.","Habiter près de chez Mme Roux.","Avoir son permis de conduire.","Avoir déjà gardé des enfants."]}'::jsonb, '{"answer":3}'::jsonb, 'Quảng cáo ghi « Expérience demandée ».'),
  ('lo51tcfce11q03', 'lo51tcfce11', 3, 'qcm', 'Où ont lieu les cours ?', '{"doc":"<p><strong>COURS DE GUITARE</strong></p><p>Professeur diplômé donne cours à domicile.</p><p>Débutants bienvenus. Premier cours offert.</p>","options":["Chez le professeur.","Dans une école de musique.","Chez l''élève.","En ligne, par vidéo."]}'::jsonb, '{"answer":2}'::jsonb, '« donne cours à domicile »: dạy tại nhà học viên.'),
  ('lo51tcfce11q04', 'lo51tcfce11', 4, 'qcm', 'Que propose la personne qui a perdu son chat ?', '{"doc":"<p><strong>PERDU</strong></p><p>Chat gris et blanc, nommé Filou, perdu près du parc Monceau le 3 juin.</p><p>Récompense. Tél. : 07 88 12 45 63</p>","options":["Des photos de son chat.","Une récompense.","Une visite du parc Monceau.","Un autre chat à adopter."]}'::jsonb, '{"answer":1}'::jsonb, 'Chủ mèo ghi « Récompense ».'),
  ('lo51tcfce11q05', 'lo51tcfce11', 5, 'qcm', 'Que doivent faire les personnes qui veulent vendre ?', '{"doc":"<p><strong>Vide-grenier</strong></p><p>Dimanche 12 mai, place de l''Église, de 8 h à 17 h.</p><p>Inscription des vendeurs à la mairie avant le 5 mai.</p>","options":["Payer leur place le jour même.","S''inscrire à la mairie.","Arriver à la place à 8 h sans inscription.","Téléphoner à l''église."]}'::jsonb, '{"answer":1}'::jsonb, 'Người bán phải « Inscription des vendeurs à la mairie avant le 5 mai ».'),
  ('lo51tcfce11q06', 'lo51tcfce11', 6, 'qcm', 'Combien de personnes peuvent encore partir avec le conducteur ?', '{"doc":"<p><strong>Covoiturage</strong></p><p>Je pars de Lille pour Bruxelles chaque vendredi à 18 h. Il me reste deux places. Participation : 8 € par personne.</p>","options":["Trois, en comptant le conducteur.","Une seule.","Huit.","Deux."]}'::jsonb, '{"answer":3}'::jsonb, 'Tài xế ghi « Il me reste deux places ». 8 € là tiền góp mỗi người.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-1 #5 Lecture TCF : messages du quotidien (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce12', 'practice', 'Lecture TCF : messages du quotidien', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• retirer (une commande) : nhận (đơn hàng)\n• une ordonnance : đơn thuốc\n• comme prévu : như dự kiến\n• gratuit (adjectif) : miễn phí\n• l''accueil (nom masculin) : quầy tiếp đón","explications":"• « et non… comme prévu » báo một thay đổi: câu trả lời là thứ đứng TRƯỚC « et non ».\n• Câu hỏi « Que répond… » cần cả câu trả lời: từ chối, đồng ý, hay đề nghị khác.","isPremium":true,"price":19000,"kyNang":"TCF-CE-1","vong":"on","thuTu":5}'::jsonb, '2026-11-16T10:00:11.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce12q01', 'lo51tcfce12', 1, 'qcm', 'Où est Léo ?', '{"doc":"<p>Papa,</p><p>J''ai oublié mes clés. Je suis chez Julie, au numéro 8. Tu peux m''appeler quand tu rentres ?</p><p>Léo</p>","options":["Chez une amie.","Devant la maison, sans ses clés.","À l''école avec Julie.","Chez son père au travail."]}'::jsonb, '{"answer":0}'::jsonb, 'Léo viết « Je suis chez Julie, au numéro 8 ».'),
  ('lo51tcfce12q02', 'lo51tcfce12', 2, 'qcm', 'Que faut-il apporter pour retirer la commande ?', '{"doc":"<p><strong>Pharmacie du Centre</strong></p><p>Votre commande est prête.</p><p>Vous pouvez la retirer à partir de demain, 10 h, avec votre ordonnance.</p>","options":["Le ticket de caisse de la commande.","La carte bancaire seulement.","Une pièce d''identité et une photo.","L''ordonnance."]}'::jsonb, '{"answer":3}'::jsonb, 'Hiệu thuốc dặn mang « votre ordonnance ».'),
  ('lo51tcfce12q03', 'lo51tcfce12', 3, 'qcm', 'Qu''est-ce qui change ?', '{"doc":"<p>Bonjour à tous,</p><p>La réunion des parents d''élèves aura lieu jeudi à 18 h 30 dans la salle 4, et non dans la salle 2 comme prévu.</p><p>La directrice</p>","options":["Le jour de la réunion des parents.","L''heure du début de la réunion.","La salle de la réunion.","La personne qui organise la réunion."]}'::jsonb, '{"answer":2}'::jsonb, 'Họp ở « la salle 4, et non dans la salle 2 comme prévu ».'),
  ('lo51tcfce12q04', 'lo51tcfce12', 4, 'qcm', 'Combien paie-t-on pour 20 minutes ?', '{"doc":"<p><strong>Parking Saint-Jean</strong></p><p>Gratuit les 30 premières minutes.</p><p>Ensuite : 2 € par heure.</p>","options":["30 centimes par minute.","Rien.","2 €, comme pour une heure.","1 €, la moitié d''une heure."]}'::jsonb, '{"answer":1}'::jsonb, 'Bãi xe « Gratuit les 30 premières minutes »: 20 phút thì không mất tiền.'),
  ('lo51tcfce12q05', 'lo51tcfce12', 5, 'qcm', 'Que répond Lou à l''invitation de samedi ?', '{"doc":"<p>Coucou Sami,</p><p>Merci pour ton invitation ! Je ne peux pas venir samedi soir, je travaille. Mais je suis libre dimanche midi, si tu veux déjeuner.</p><p>Lou</p>","options":["Elle ne répond pas à la question.","Elle refuse et propose un autre moment.","Elle accepte avec plaisir.","Elle demande à venir avec une amie."]}'::jsonb, '{"answer":1}'::jsonb, 'Lou nói « Je ne peux pas venir samedi soir » rồi đề nghị « dimanche midi ».'),
  ('lo51tcfce12q06', 'lo51tcfce12', 6, 'qcm', 'Que peut-on faire si on n''a pas de bonnet ?', '{"doc":"<p><strong>Piscine des Tilleuls</strong></p><p>Bonnet obligatoire. Vente de bonnets à l''accueil : 3 €.</p>","options":["En acheter un à l''accueil.","En emprunter un gratuitement à l''accueil.","Nager sans bonnet dans le petit bassin.","Revenir un autre jour sans payer."]}'::jsonb, '{"answer":0}'::jsonb, 'Thông báo ghi « Vente de bonnets à l''accueil : 3 € »: mua tại quầy.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-1 #6 Lecture TCF : documents courts, révision (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce13', 'practice', 'Lecture TCF : documents courts, révision', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un colis : bưu kiện\n• un facteur : người đưa thư\n• la peinture fraîche : sơn còn ướt\n• les congés : kỳ nghỉ\n• en cas de retard : nếu trả muộn","explications":"• Bài ôn: mỗi câu dưới 40 giây; tài liệu ngắn, thường một chi tiết quyết định.\n• Ba mốc giờ trong một tin nhắn: tìm động từ gắn với câu hỏi (« je t''attends »).","isPremium":true,"price":19000,"kyNang":"TCF-CE-1","vong":"chot","thuTu":6}'::jsonb, '2026-11-16T10:00:12.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce13q01', 'lo51tcfce13', 1, 'qcm', 'Combien paie un enfant de 12 ans ?', '{"doc":"<p><strong>MUSÉE D''ART</strong></p><p>Entrée : 10 €</p><p>Gratuit pour les moins de 18 ans.</p>","options":["5 €, la moitié du prix.","Rien.","10 €, comme les adultes.","18 €."]}'::jsonb, '{"answer":1}'::jsonb, '« Gratuit pour les moins de 18 ans »: trẻ 12 tuổi được miễn phí.'),
  ('lo51tcfce13q02', 'lo51tcfce13', 2, 'qcm', 'Où se trouve le colis ?', '{"doc":"<p>Mme Leroy,</p><p>Votre colis n''a pas pu être livré : vous étiez absente. Il est disponible au bureau de poste, rue Pasteur, pendant 15 jours.</p><p>Le facteur</p>","options":["Devant la porte de Mme Leroy.","Chez une voisine de Mme Leroy.","Au bureau de poste.","Chez le facteur, à son domicile."]}'::jsonb, '{"answer":2}'::jsonb, 'Gói hàng « est disponible au bureau de poste, rue Pasteur ».'),
  ('lo51tcfce13q03', 'lo51tcfce13', 3, 'qcm', 'Que signifie ce panneau ?', '{"doc":"<p><strong>ATTENTION</strong></p><p>Peinture fraîche. Ne pas toucher.</p>","options":["Il faut repeindre le mur aujourd''hui.","La peinture est en vente ici.","On peut s''asseoir après la peinture.","Il ne faut pas toucher le mur."]}'::jsonb, '{"answer":3}'::jsonb, 'Biển ghi « Ne pas toucher »: sơn còn ướt.'),
  ('lo51tcfce13q04', 'lo51tcfce13', 4, 'qcm', 'À quelle heure Nadia donne-t-elle rendez-vous ?', '{"doc":"<p>Salut,</p><p>Le concert de ce soir commence à 20 h, mais les portes ouvrent à 19 h. Je t''attends devant l''entrée à 19 h 15.</p><p>Nadia</p>","options":["À 19 h, quand les portes ouvrent.","À 20 h 15, après le début.","À 19 h 15.","À 20 h, au début du concert."]}'::jsonb, '{"answer":2}'::jsonb, 'Nadia hẹn « devant l''entrée à 19 h 15 ».'),
  ('lo51tcfce13q05', 'lo51tcfce13', 5, 'qcm', 'Que conseille la boulangerie à ses clients en août ?', '{"doc":"<p><strong>Boulangerie Martin</strong></p><p>Fermée pour congés du 1er au 21 août.</p><p>Pendant ce temps, rendez-vous à la boulangerie du marché.</p>","options":["De commander leur pain par téléphone.","D''acheter leur pain avant le 1er août.","D''aller dans une autre boulangerie.","De revenir après le 1er août."]}'::jsonb, '{"answer":2}'::jsonb, 'Tiệm khuyên « rendez-vous à la boulangerie du marché ».'),
  ('lo51tcfce13q06', 'lo51tcfce13', 6, 'qcm', 'Que se passe-t-il si on rend un livre en retard ?', '{"doc":"<p><strong>Bibliothèque</strong></p><p>Les livres empruntés doivent être rendus avant le 30 juin.</p><p>En cas de retard : 0,50 € par jour.</p>","options":["On paie une petite somme par jour.","On ne peut plus jamais emprunter de livres.","On doit acheter un livre neuf.","On reçoit un avertissement par courrier."]}'::jsonb, '{"answer":0}'::jsonb, 'Trả muộn thì « 0,50 € par jour ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-2 #3 Lecture TCF : courriels professionnels (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce14', 'practice', 'Lecture TCF : courriels professionnels', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• prévenir (verbe) : báo trước\n• une candidature retenue : hồ sơ được chọn\n• dans les plus brefs délais : trong thời gian sớm nhất\n• être au courant : nắm được tình hình\n• un devis : bản báo giá","explications":"• Email công việc: dòng « Objet » cho biết chủ đề, câu cuối thường là YÊU CẦU.\n• « alors que » đặt hai con số cạnh nhau để chỉ ra chỗ không khớp.","isPremium":true,"price":19000,"kyNang":"TCF-CE-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-16T10:00:13.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce14q01', 'lo51tcfce14', 1, 'qcm', 'Que doivent faire les salariés absents le 15 mars ?', '{"doc":"<p><strong>Objet :</strong> formation sécurité</p><p>Bonjour à tous,</p><p>Une formation obligatoire sur la sécurité incendie aura lieu le 15 mars de 14 h à 16 h. Les personnes qui ne peuvent pas y assister doivent prévenir leur responsable avant le 10 mars, afin de s''inscrire à la session d''avril.</p><p>Le service des ressources humaines</p>","options":["Informer leur responsable avant le 10 mars.","Rien, la formation n''est pas obligatoire.","Envoyer un certificat médical aux ressources humaines.","Suivre la formation en ligne chez eux."]}'::jsonb, '{"answer":0}'::jsonb, 'Người vắng mặt « doivent prévenir leur responsable avant le 10 mars ».'),
  ('lo51tcfce14q02', 'lo51tcfce14', 2, 'qcm', 'Que demande Claire Fontaine à M. Caron ?', '{"doc":"<p>Bonjour Monsieur Caron,</p><p>Suite à notre entretien de vendredi, j''ai le plaisir de vous annoncer que votre candidature a été retenue pour le poste d''assistant commercial. Vous commencerez le 2 mai. Merci de nous confirmer votre accord par retour de courriel.</p><p>Claire Fontaine</p>","options":["D''envoyer son CV et ses diplômes.","De passer un deuxième entretien vendredi.","De commencer à travailler dès lundi.","De répondre pour accepter le poste."]}'::jsonb, '{"answer":3}'::jsonb, 'Bà Fontaine viết « Merci de nous confirmer votre accord par retour de courriel ».'),
  ('lo51tcfce14q03', 'lo51tcfce14', 3, 'qcm', 'Quel est le but de ce courriel ?', '{"doc":"<p><strong>Objet :</strong> panne de l''ascenseur</p><p>Madame, Monsieur,</p><p>L''ascenseur de notre immeuble est en panne depuis trois semaines. Plusieurs habitants âgés ne peuvent plus sortir de chez eux. Malgré nos appels, aucun technicien n''est venu. Nous vous demandons d''intervenir dans les plus brefs délais.</p><p>Les locataires du 12 rue Voltaire</p>","options":["Remercier le technicien pour son travail.","Inviter les voisins à une réunion.","Annoncer des travaux dans l''immeuble.","Demander une réparation rapide."]}'::jsonb, '{"answer":3}'::jsonb, 'Người thuê « vous demandons d''intervenir dans les plus brefs délais ».'),
  ('lo51tcfce14q04', 'lo51tcfce14', 4, 'qcm', 'Qui va s''occuper des dossiers d''Aurélie ?', '{"doc":"<p>Chère Aurélie,</p><p>Je pars en congé maternité à la fin du mois. C''est Julien qui suivra tes dossiers en attendant mon retour en septembre. N''hésite pas à le contacter, il est au courant de tout.</p><p>Bises, Sandra</p>","options":["Aurélie elle-même, seule.","Un collègue de Sandra.","Personne avant le mois de septembre.","Sandra, jusqu''en septembre."]}'::jsonb, '{"answer":1}'::jsonb, 'Sandra viết « C''est Julien qui suivra tes dossiers ».'),
  ('lo51tcfce14q05', 'lo51tcfce14', 5, 'qcm', 'Pourquoi conseille-t-on de réserver son repas ?', '{"doc":"<p><strong>Objet :</strong> nouvelle cafétéria</p><p>Chers collègues,</p><p>La nouvelle cafétéria du deuxième étage ouvre lundi. Pour éviter l''attente, nous vous proposons de réserver votre repas la veille sur l''intranet. Les plats non réservés seront servis dans la limite des stocks disponibles.</p>","options":["Pour choisir sa table à l''avance.","Pour ne pas attendre.","Pour payer moins cher le repas du midi.","Parce que la cafétéria ferme le lundi."]}'::jsonb, '{"answer":1}'::jsonb, 'Đặt trước « Pour éviter l''attente ».'),
  ('lo51tcfce14q06', 'lo51tcfce14', 6, 'qcm', 'Quel problème Paul Morin signale-t-il ?', '{"doc":"<p>Bonjour,</p><p>Je vous écris au sujet de la facture n° 2215. Le montant indiqué est de 340 €, alors que le devis accepté était de 290 €. Pourriez-vous m''expliquer cette différence ?</p><p>Paul Morin</p>","options":["La facture est plus élevée que prévu.","Le devis a été perdu par l''entreprise.","Le travail n''est pas encore terminé.","La facture n''est jamais arrivée."]}'::jsonb, '{"answer":0}'::jsonb, 'Hoá đơn « 340 € » trong khi báo giá « était de 290 € ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-2 #4 Lecture TCF : informations pratiques (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce15', 'practice', 'Lecture TCF : informations pratiques', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• au lieu de : thay vì\n• à jeun : bụng đói\n• y compris : kể cả\n• la langue des signes : ngôn ngữ ký hiệu\n• la canicule : đợt nắng nóng\n• un dossard : số áo vận động viên","explications":"• Câu hỏi « Que suggère le texte ? » cần suy luận từ một chi tiết (ví dụ « parties en dix jours »).\n• « X, lui, … » nhấn mạnh X khác các thứ khác: chú ý khi câu hỏi nói về X.","isPremium":true,"price":19000,"kyNang":"TCF-CE-2","vong":"on","thuTu":4}'::jsonb, '2026-11-16T10:00:14.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce15q01', 'lo51tcfce15', 1, 'qcm', 'Qui peut obtenir cette carte ?', '{"doc":"<p><strong>Carte de bus jeunes</strong></p><p>Les jeunes de moins de 26 ans peuvent obtenir une carte de bus à 15 € par mois au lieu de 40 €. Il suffit de présenter une pièce d''identité et une photo à l''agence de la gare.</p>","options":["Les étudiants de plus de 26 ans.","Les personnes de moins de 26 ans.","Seulement les personnes qui habitent près de la gare.","Tous les habitants qui paient 40 € par mois."]}'::jsonb, '{"answer":1}'::jsonb, 'Thẻ dành cho « Les jeunes de moins de 26 ans ».'),
  ('lo51tcfce15q02', 'lo51tcfce15', 2, 'qcm', 'Quel conseil est donné aux donneurs ?', '{"doc":"<p><strong>Don du sang</strong></p><p>Une collecte aura lieu samedi à la salle des fêtes. Pour donner son sang, il faut avoir entre 18 et 70 ans, peser plus de 50 kg et ne pas venir à jeun : un petit-déjeuner est conseillé.</p>","options":["Manger avant de venir.","Ne rien manger le matin de la collecte.","Arriver à la salle très tôt le matin.","Venir avec un ami de plus de 70 ans."]}'::jsonb, '{"answer":0}'::jsonb, 'Không đến khi bụng đói: « ne pas venir à jeun : un petit-déjeuner est conseillé ».'),
  ('lo51tcfce15q03', 'lo51tcfce15', 3, 'qcm', 'Où faut-il jeter les bouteilles en verre ?', '{"doc":"<p><strong>Recyclage</strong></p><p>À partir du 1er janvier, tous les emballages en plastique iront dans la poubelle jaune, y compris les pots de yaourt et les films plastiques. Le verre, lui, reste à déposer dans les conteneurs de rue.</p>","options":["Dans la poubelle jaune, avec le plastique.","Dans la poubelle des déchets ménagers.","À la mairie, une fois par mois.","Dans les conteneurs de rue."]}'::jsonb, '{"answer":3}'::jsonb, '« Le verre, lui, reste à déposer dans les conteneurs de rue ».'),
  ('lo51tcfce15q04', 'lo51tcfce15', 4, 'qcm', 'Pourquoi faut-il réserver ?', '{"doc":"<p><strong>Musée de la Marine : nouveauté</strong></p><p>Le musée propose désormais des visites guidées en langue des signes, le premier samedi de chaque mois. La réservation est obligatoire, le nombre de places étant limité à quinze.</p>","options":["Les places sont peu nombreuses.","Le musée est fermé le samedi.","Le guide ne vient que sur demande écrite.","La visite coûte plus cher que les autres."]}'::jsonb, '{"answer":0}'::jsonb, 'Phải đặt vì « le nombre de places étant limité à quinze ».'),
  ('lo51tcfce15q05', 'lo51tcfce15', 5, 'qcm', 'Que recommande-t-on de faire pour les voisins âgés ?', '{"doc":"<p><strong>Canicule : recommandations</strong></p><p>Buvez de l''eau régulièrement, même sans avoir soif. Évitez de sortir entre 12 h et 16 h. Prenez des nouvelles de vos voisins âgés ou isolés.</p>","options":["Les emmener à la piscine l''après-midi.","Leur apporter des boissons sucrées.","Leur conseiller de sortir entre 12 h et 16 h.","Leur rendre visite ou les appeler."]}'::jsonb, '{"answer":3}'::jsonb, 'Khuyến nghị « Prenez des nouvelles de vos voisins âgés ou isolés »: hỏi thăm họ.'),
  ('lo51tcfce15q06', 'lo51tcfce15', 6, 'qcm', 'Que suggère le texte ?', '{"doc":"<p><strong>Inscription au marathon</strong></p><p>Les inscriptions sont ouvertes jusqu''au 1er avril ou jusqu''à ce que les 5 000 dossards soient attribués. L''an dernier, toutes les places étaient parties en dix jours.</p>","options":["Il vaut mieux s''inscrire rapidement.","Il reste toujours des places en avril.","Le marathon a été annulé l''an dernier.","Les inscriptions durent toute l''année."]}'::jsonb, '{"answer":0}'::jsonb, 'Năm ngoái « toutes les places étaient parties en dix jours »: nên đăng ký sớm.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-2 #5 Lecture TCF : lettres personnelles (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce16', 'practice', 'Lecture TCF : lettres personnelles', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• tricoter (verbe) : đan\n• vallonné (adjectif) : nhiều dốc\n• accueillir (verbe) : đón tiếp\n• supprimé (participe) : bị huỷ\n• avec mention : đạt loại khá, giỏi\n• être partant : sẵn sàng tham gia","explications":"• Thư cá nhân: lý do viết thư thường ở câu ĐẦU.\n• « Grâce à » đi với kết quả tốt, « à cause de » đi với kết quả xấu: giúp tìm nguyên nhân.","isPremium":true,"price":19000,"kyNang":"TCF-CE-2","vong":"on","thuTu":5}'::jsonb, '2026-11-16T10:00:15.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce16q01', 'lo51tcfce16', 1, 'qcm', 'Que promet Chloé à sa grand-mère ?', '{"doc":"<p>Chère Mamie,</p><p>Merci pour le pull que tu m''as tricoté ! Il est très chaud et toutes mes amies l''adorent. Je viendrai te voir pendant les vacances de février, et cette fois, c''est moi qui ferai la cuisine.</p><p>Je t''embrasse, Chloé</p>","options":["De l''appeler chaque semaine.","De lui préparer un repas.","De l''inviter chez ses amies.","De lui tricoter un pull à son tour."]}'::jsonb, '{"answer":1}'::jsonb, 'Chloé hứa « c''est moi qui ferai la cuisine ».'),
  ('lo51tcfce16q02', 'lo51tcfce16', 2, 'qcm', 'De quoi Alex se plaint-il ?', '{"doc":"<p>Salut Ben,</p><p>Je suis bien arrivé à Lisbonne. La ville est magnifique mais très vallonnée : mes jambes me font mal ! Demain, je prends le tram jusqu''à la mer. Je rentre jeudi, je t''apporterai des pâtisseries.</p><p>Alex</p>","options":["Des rues en pente.","Du prix élevé des pâtisseries.","Du mauvais temps à Lisbonne.","Des trams toujours en retard."]}'::jsonb, '{"answer":0}'::jsonb, 'Alex viết thành phố « très vallonnée : mes jambes me font mal ».'),
  ('lo51tcfce16q03', 'lo51tcfce16', 3, 'qcm', 'Pourquoi Karine et Malik écrivent-ils ?', '{"doc":"<p>Chers amis,</p><p>Après dix ans à Paris, nous avons décidé de nous installer à la campagne, près d''Angers. Nous avons acheté une vieille maison avec un grand jardin. Il y a beaucoup de travaux, mais nous sommes impatients de vous y accueillir !</p><p>Karine et Malik</p>","options":["Pour demander de l''aide pour les travaux.","Pour annoncer leur déménagement.","Pour inviter leurs amis à leur mariage.","Pour vendre leur appartement de Paris."]}'::jsonb, '{"answer":1}'::jsonb, 'Họ báo « nous avons décidé de nous installer à la campagne ».'),
  ('lo51tcfce16q04', 'lo51tcfce16', 4, 'qcm', 'Pourquoi Fanny n''est-elle pas venue ?', '{"doc":"<p>Coucou Mélanie,</p><p>Je suis désolée de ne pas être venue à ta fête samedi. Mon train a été supprimé à la dernière minute et il n''y en avait pas d''autre. J''espère que tu as passé une belle soirée. On se voit bientôt ?</p><p>Fanny</p>","options":["Parce qu''elle avait oublié la date.","Parce qu''elle était malade samedi.","À cause d''un problème de transport.","Parce qu''elle devait travailler tard."]}'::jsonb, '{"answer":2}'::jsonb, 'Fanny nói « Mon train a été supprimé à la dernière minute ».'),
  ('lo51tcfce16q05', 'lo51tcfce16', 5, 'qcm', 'Qu''est-ce que les cours ont apporté à Yasmine ?', '{"doc":"<p>Cher Monsieur Duval,</p><p>Je tenais à vous remercier pour vos cours de mathématiques cette année. Grâce à vos explications patientes, j''ai enfin repris confiance en moi et j''ai obtenu mon baccalauréat avec mention.</p><p>Avec ma reconnaissance, Yasmine</p>","options":["L''envie de devenir professeure de mathématiques.","Plus de confiance en elle.","Une place dans une grande école.","Des notes parfaites dans toutes les matières."]}'::jsonb, '{"answer":1}'::jsonb, 'Yasmine viết « j''ai enfin repris confiance en moi ».'),
  ('lo51tcfce16q06', 'lo51tcfce16', 6, 'qcm', 'Pourquoi Rémi demande-t-il une réponse rapide ?', '{"doc":"<p>Salut Hugo,</p><p>Tu te souviens du projet de voyage au Maroc ? J''ai trouvé des billets à moitié prix pour octobre, mais il faut réserver avant vendredi. Tu es toujours partant ? Réponds-moi vite !</p><p>Rémi</p>","options":["Les billets ne sont plus disponibles en octobre.","Hugo n''a pas répondu à son dernier message.","L''offre de billets se termine bientôt.","Il part au Maroc dès demain matin."]}'::jsonb, '{"answer":2}'::jsonb, 'Vé rẻ « il faut réserver avant vendredi ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-2 #6 Lecture TCF : textes B1, révision (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce17', 'practice', 'Lecture TCF : textes B1, révision', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une perceuse : máy khoan\n• la marche à suivre : các bước cần làm\n• à ma charge : do tôi trả\n• une animation : hoạt động vui chơi\n• les restes : đồ ăn thừa","explications":"• Bài chốt B1: câu hỏi hỏi điều KIỆN, LÝ DO hoặc ĐỀ NGHỊ; đọc kỹ câu chứa từ khoá.\n• Một tài liệu có hai câu hỏi trong thư (« la marche à suivre » và « les frais »): đáp án đúng gồm cả hai.","isPremium":true,"price":19000,"kyNang":"TCF-CE-2","vong":"chot","thuTu":6}'::jsonb, '2026-11-16T10:00:16.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce17q01', 'lo51tcfce17', 1, 'qcm', 'Combien de temps peut-on garder un outil ?', '{"doc":"<p><strong>Nouveau service à la médiathèque</strong></p><p>Vous pouvez désormais emprunter des outils : perceuse, échelle, scie. Le prêt est gratuit pour les abonnés, pour une durée de trois jours maximum.</p>","options":["Aussi longtemps qu''on le souhaite.","Une seule journée, sans exception.","Trois semaines, comme un livre.","Trois jours au maximum."]}'::jsonb, '{"answer":3}'::jsonb, 'Mượn tối đa « trois jours maximum ».'),
  ('lo51tcfce17q02', 'lo51tcfce17', 2, 'qcm', 'Que veut savoir Nicolas Petit ?', '{"doc":"<p>Madame, Monsieur,</p><p>J''ai acheté en ligne une machine à café qui ne fonctionne pas. Je souhaite la renvoyer. Pouvez-vous m''indiquer la marche à suivre et me dire si les frais de retour sont à ma charge ?</p><p>Nicolas Petit</p>","options":["Où acheter une autre machine moins chère.","Comment réparer lui-même la machine.","Comment renvoyer la machine et qui paie le retour.","Quand sa machine à café sera livrée."]}'::jsonb, '{"answer":2}'::jsonb, 'Anh hỏi « la marche à suivre » và « si les frais de retour sont à ma charge ».'),
  ('lo51tcfce17q03', 'lo51tcfce17', 3, 'qcm', 'Quel avantage est offert ce dimanche ?', '{"doc":"<p><strong>Journée sans voiture</strong></p><p>Dimanche, le centre-ville sera fermé aux voitures de 10 h à 18 h. Les bus seront gratuits toute la journée. Des animations pour les enfants auront lieu sur la place centrale.</p>","options":["Les transports en commun sont gratuits.","Le parking du centre est gratuit toute la journée.","Les vélos sont prêtés gratuitement à la mairie.","Les commerces font des réductions."]}'::jsonb, '{"answer":0}'::jsonb, '« Les bus seront gratuits toute la journée ».'),
  ('lo51tcfce17q04', 'lo51tcfce17', 4, 'qcm', 'Que pense faire Inès ?', '{"doc":"<p>Salut Clara,</p><p>J''ai commencé mon nouveau travail lundi. Mes collègues sont sympas, mais les journées sont longues et je mets une heure pour y aller. Je réfléchis à déménager plus près.</p><p>Inès</p>","options":["Changer de travail rapidement.","Changer de logement.","Acheter une voiture pour aller au travail.","Demander à travailler moins d''heures."]}'::jsonb, '{"answer":1}'::jsonb, 'Inès viết « Je réfléchis à déménager plus près ».'),
  ('lo51tcfce17q05', 'lo51tcfce17', 5, 'qcm', 'Que doivent apporter les participants ?', '{"doc":"<p><strong>Atelier cuisine anti-gaspillage</strong></p><p>Apprenez à cuisiner avec les restes de votre réfrigérateur ! Atelier gratuit, le mardi à 18 h. Apportez un ingrédient que vous ne savez pas comment utiliser.</p>","options":["De l''argent pour payer l''atelier.","Un aliment qu''ils ne savent pas cuisiner.","Leur propre matériel de cuisine.","Un plat déjà préparé à la maison."]}'::jsonb, '{"answer":1}'::jsonb, 'Người tham gia « Apportez un ingrédient que vous ne savez pas comment utiliser ».'),
  ('lo51tcfce17q06', 'lo51tcfce17', 6, 'qcm', 'Pourquoi les salariés veulent-ils travailler chez eux ?', '{"doc":"<p><strong>Résultats de l''enquête</strong></p><p>Selon une enquête auprès de 2 000 salariés, 62 % aimeraient travailler depuis chez eux au moins un jour par semaine. La principale raison citée est le temps perdu dans les transports.</p>","options":["Pour gagner un meilleur salaire.","Pour éviter de perdre du temps dans les trajets.","Parce que leur bureau est trop bruyant.","Pour passer moins de temps avec leurs collègues."]}'::jsonb, '{"answer":1}'::jsonb, 'Lý do chính là « le temps perdu dans les transports ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-3 #3 Lecture TCF : tribunes et éditoriaux (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce18', 'practice', 'Lecture TCF : tribunes et éditoriaux', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une carence : sự thiếu chất\n• trancher (verbe) : phân xử, quyết định\n• forcément (adverbe) : tất yếu\n• flâner (verbe) : dạo chơi\n• sacrifier (verbe) : hy sinh, bỏ đi","explications":"• « Le vrai défi est ailleurs », « Mais il laisse une question »: ý tác giả nằm SAU những cụm này.\n• Bài B2 thường nêu ý phổ biến (« On annonce », « Les parents y voient ») rồi lật lại bằng « Pourtant ».","isPremium":true,"price":19000,"kyNang":"TCF-CE-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-16T10:00:17.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce18q01', 'lo51tcfce18', 1, 'qcm', 'Selon l''auteur, quel est le principal défi ?', '{"doc":"<p><strong>Les cantines doivent-elles devenir végétariennes ?</strong></p><p>Certaines villes servent désormais un repas végétarien par jour dans les écoles. Les opposants craignent des carences. Les nutritionnistes sont pourtant clairs : un menu végétarien équilibré couvre tous les besoins d''un enfant. Le vrai défi est ailleurs : former les cuisiniers, pour que ces plats soient bons et que les enfants les mangent.</p>","options":["Réduire le prix des repas servis à la cantine.","Éviter les carences chez les enfants.","Préparer des plats végétariens appréciés des enfants.","Convaincre les nutritionnistes de l''intérêt du projet."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả viết « Le vrai défi est ailleurs : former les cuisiniers, pour que ces plats soient bons ».'),
  ('lo51tcfce18q02', 'lo51tcfce18', 2, 'qcm', 'Qu''est-ce qui freine la confiance, selon l''auteur ?', '{"doc":"<p><strong>Faut-il avoir peur des voitures autonomes ?</strong></p><p>On nous promet des routes plus sûres, puisque la plupart des accidents sont dus à des erreurs humaines. L''argument est solide. Mais il laisse une question sans réponse : en cas d''accident, qui sera responsable ? Le constructeur, le propriétaire, le programmeur ? Tant que la loi ne tranchera pas, la confiance restera fragile.</p>","options":["Le prix trop élevé des voitures autonomes.","Le nombre élevé d''accidents de voitures autonomes.","L''absence de règles claires sur la responsabilité.","Le refus des constructeurs de vendre ces voitures."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả viết « Tant que la loi ne tranchera pas, la confiance restera fragile ».'),
  ('lo51tcfce18q03', 'lo51tcfce18', 3, 'qcm', 'Que pense l''auteur des cahiers de vacances ?', '{"doc":"<p><strong>Les devoirs de vacances, une tradition à revoir</strong></p><p>Chaque été, des millions de cahiers de vacances sont vendus. Les parents y voient une façon de ne pas tout oublier. Mais les vacances servent aussi à autre chose : s''ennuyer, lire pour le plaisir, découvrir. Remplir des exercices ne développe pas forcément la curiosité, qui est pourtant le meilleur moteur de l''apprentissage.</p>","options":["Ils devraient être distribués gratuitement par l''école.","Ils sont trop difficiles pour les jeunes enfants.","Ils ne développent pas forcément la curiosité.","Ils sont indispensables pour ne rien oublier."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả viết « Remplir des exercices ne développe pas forcément la curiosité ».'),
  ('lo51tcfce18q04', 'lo51tcfce18', 4, 'qcm', 'Selon l''auteur, pourquoi certains petits commerces réussissent-ils ?', '{"doc":"<p><strong>Les petits commerces ne sont pas condamnés</strong></p><p>On annonce depuis des années la mort des commerces de proximité face au commerce en ligne. Pourtant, dans de nombreux quartiers, des librairies, des fromageries et des épiceries ouvrent. Leur secret : offrir ce qu''un site internet ne peut pas donner, le conseil, la relation et le plaisir de flâner.</p>","options":["Ils proposent aussi la livraison à domicile.","Ils offrent une relation et des conseils.","Ils vendent moins cher que les sites internet.","Ils sont ouverts plus tard le soir."]}'::jsonb, '{"answer":1}'::jsonb, 'Bí quyết là « le conseil, la relation et le plaisir de flâner ».'),
  ('lo51tcfce18q05', 'lo51tcfce18', 5, 'qcm', 'Quel argument l''auteur avance-t-il en faveur du sport ?', '{"doc":"<p><strong>Le sport à l''école mérite mieux</strong></p><p>L''éducation physique est souvent la première matière sacrifiée quand les emplois du temps sont chargés. C''est une erreur. Les élèves qui bougent régulièrement se concentrent mieux en classe. Augmenter les heures de sport ne ferait donc pas perdre de temps aux autres matières : cela les aiderait.</p>","options":["Il permet de former de futurs champions.","Il améliore la concentration des élèves.","Il réduit le nombre d''heures de cours.","Il remplace les cours de sciences naturelles."]}'::jsonb, '{"answer":1}'::jsonb, 'Tác giả nói học sinh vận động đều « se concentrent mieux en classe ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-3 #4 Lecture TCF : société et travail (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce19', 'practice', 'Lecture TCF : société et travail', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• trier (verbe) : sàng lọc\n• un préjugé : định kiến\n• sanctionner (verbe) : xử phạt\n• rompre la solitude : phá vỡ sự cô đơn\n• un atout : lợi thế","explications":"• « ne… que si » = chỉ khi: điều kiện tác giả đặt ra là phần sau « si ».\n• « Encore faut-il que… » nêu điều kiện cần thiết: thường là đáp án cho câu hỏi về điều kiện.","isPremium":true,"price":19000,"kyNang":"TCF-CE-3","vong":"on","thuTu":4}'::jsonb, '2026-11-16T10:00:18.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce19q01', 'lo51tcfce19', 1, 'qcm', 'Quelle condition l''auteur pose-t-il ?', '{"doc":"<p><strong>L''entretien d''embauche à l''ère des algorithmes</strong></p><p>De grandes entreprises utilisent des logiciels pour trier les CV. Elles y gagnent du temps. Mais ces programmes reproduisent parfois les préjugés contenus dans les données qui ont servi à les entraîner. Un outil n''est neutre que si l''on vérifie régulièrement ses décisions.</p>","options":["Contrôler régulièrement les décisions des logiciels.","Interdire les logiciels de tri des candidatures.","Embaucher plus de recruteurs pour lire les CV.","Utiliser les logiciels seulement pour les petits postes."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả viết « Un outil n''est neutre que si l''on vérifie régulièrement ses décisions ».'),
  ('lo51tcfce19q02', 'lo51tcfce19', 2, 'qcm', 'Quelle idée l''auteur souligne-t-il ?', '{"doc":"<p><strong>Retraités actifs</strong></p><p>Beaucoup de retraités consacrent leur temps libre au bénévolat : aide aux devoirs, accompagnement de personnes malades, gestion d''associations. Ce travail invisible représente des milliers d''heures chaque année. Sans eux, de nombreuses associations devraient tout simplement fermer leurs portes.</p>","options":["Les retraités sont essentiels aux associations.","Les associations emploient trop de retraités.","Les retraités ont moins de temps libre qu''avant.","Les retraités devraient être payés pour leur travail."]}'::jsonb, '{"answer":0}'::jsonb, '« Sans eux, de nombreuses associations devraient tout simplement fermer leurs portes ».'),
  ('lo51tcfce19q03', 'lo51tcfce19', 3, 'qcm', 'Que reproche l''auteur aux entreprises qui sanctionnent l''erreur ?', '{"doc":"<p><strong>Le droit à l''erreur au travail</strong></p><p>Dans beaucoup d''entreprises, l''erreur est sanctionnée. Résultat : les salariés n''osent plus proposer d''idées nouvelles. Les entreprises les plus innovantes ont compris qu''il faut accepter l''échec comme une étape normale. Celui qui ne se trompe jamais est souvent celui qui n''essaie rien.</p>","options":["Elles ne contrôlent pas assez leurs salariés.","Elles paient mal leurs employés les plus créatifs.","Elles font trop d''erreurs dans leur gestion.","Elles découragent l''innovation."]}'::jsonb, '{"answer":3}'::jsonb, 'Hậu quả: « les salariés n''osent plus proposer d''idées nouvelles ».'),
  ('lo51tcfce19q04', 'lo51tcfce19', 4, 'qcm', 'Selon l''auteur, qu''est-ce qui est nécessaire pour que cela fonctionne ?', '{"doc":"<p><strong>Les colocations intergénérationnelles</strong></p><p>Un étudiant loge chez une personne âgée en échange d''une présence le soir et de petits services. Les deux y gagnent : l''un trouve un logement peu cher, l''autre rompt sa solitude. Encore faut-il que les règles soient claires dès le départ, pour éviter les malentendus.</p>","options":["Choisir des étudiants qui étudient la médecine.","Payer un loyer élevé à la personne âgée.","Fixer des règles claires dès le début.","Habiter dans la même ville que sa famille."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả viết « Encore faut-il que les règles soient claires dès le départ ».'),
  ('lo51tcfce19q05', 'lo51tcfce19', 5, 'qcm', 'Quelle est la thèse de l''auteur ?', '{"doc":"<p><strong>Le français, langue des affaires</strong></p><p>On pense souvent que l''anglais suffit pour réussir dans les affaires. C''est oublier que le français est parlé sur cinq continents et qu''il est la langue officielle de nombreux pays d''Afrique, dont l''économie progresse rapidement. Parler français reste donc un atout professionnel réel.</p>","options":["Le français est moins parlé en Afrique qu''avant.","Il faut apprendre seulement les langues d''Asie.","L''anglais suffit pour réussir dans les affaires.","Le français reste utile dans le monde professionnel."]}'::jsonb, '{"answer":3}'::jsonb, 'Tác giả kết « Parler français reste donc un atout professionnel réel ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-3 #5 Lecture TCF : culture et loisirs (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce20', 'practice', 'Lecture TCF : culture et loisirs', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• jetable (adjectif) : dùng một lần\n• réintroduire (verbe) : thả lại (tự nhiên)\n• tiré de : chuyển thể từ\n• le mécénat : tài trợ văn hoá\n• crier au scandale : la ó phản đối","explications":"• « La question n''est plus… mais… »: đáp án nằm ở vế « mais ».\n• Phương án chép ý bị bác bỏ (« Savoir si le jeu vidéo est un art ») là bẫy.","isPremium":true,"price":19000,"kyNang":"TCF-CE-3","vong":"on","thuTu":5}'::jsonb, '2026-11-16T10:00:19.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce20q01', 'lo51tcfce20', 1, 'qcm', 'Comment l''auteur explique-t-il le succès des vinyles ?', '{"doc":"<p><strong>Le retour des vinyles</strong></p><p>Les ventes de disques vinyles augmentent chaque année, alors que la musique est disponible gratuitement en ligne. Paradoxe ? Pas vraiment. Acheter un disque, c''est posséder un objet, prendre le temps d''écouter un album entier. Dans un monde de musique jetable, le vinyle offre une forme de lenteur.</p>","options":["Ils permettent une écoute plus lente et attentive.","Ils sont vendus dans tous les supermarchés.","Ils sont moins chers que les abonnements musicaux.","Ils ont un meilleur son que la musique en ligne."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả nói vinyle « offre une forme de lenteur », nghe trọn một album.'),
  ('lo51tcfce20q02', 'lo51tcfce20', 2, 'qcm', 'Que propose l''auteur ?', '{"doc":"<p><strong>Faut-il fermer les zoos ?</strong></p><p>Les zoos sont accusés d''enfermer des animaux pour le plaisir des visiteurs. La critique est en partie juste. Mais certains zoos jouent aussi un rôle de protection : ils font naître des espèces menacées et les réintroduisent dans la nature. Plutôt que de tous les fermer, il faudrait ne garder que ceux qui ont cette mission.</p>","options":["Conserver uniquement les zoos qui protègent les espèces.","Fermer tous les zoos le plus vite possible.","Ouvrir de nouveaux zoos dans chaque ville.","Laisser les visiteurs nourrir les animaux."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả đề xuất « ne garder que ceux qui ont cette mission ».'),
  ('lo51tcfce20q03', 'lo51tcfce20', 3, 'qcm', 'Quelle est l''opinion de l''auteur ?', '{"doc":"<p><strong>Les séries remplacent-elles les livres ?</strong></p><p>Les séries télévisées occupent une place croissante dans nos soirées. Certains y voient la fin de la lecture. Je n''y crois pas. Les meilleures séries donnent souvent envie de lire le roman dont elles sont tirées. L''écran peut être une porte d''entrée vers le livre plutôt que son ennemi.</p>","options":["Les romans adaptés en séries se vendent moins bien.","Les séries vont faire disparaître les livres.","Les séries peuvent encourager la lecture.","Les séries sont de moins bonne qualité que les films."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả viết « L''écran peut être une porte d''entrée vers le livre ».'),
  ('lo51tcfce20q04', 'lo51tcfce20', 4, 'qcm', 'Pourquoi l''auteur refuse-t-il de vendre le patrimoine ?', '{"doc":"<p><strong>Le patrimoine coûte cher</strong></p><p>Entretenir les châteaux et les églises anciennes demande des sommes énormes. Certains proposent de vendre une partie de ce patrimoine à des investisseurs privés. Ce serait une erreur : une fois vendus, ces lieux pourraient être fermés au public. Mieux vaut développer le mécénat et les visites payantes.</p>","options":["Les investisseurs privés ne sont pas assez riches.","Les visites payantes rapportent déjà beaucoup.","Le public pourrait perdre l''accès à ces lieux.","L''entretien des monuments ne coûte pas cher."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả sợ « ces lieux pourraient être fermés au public ».'),
  ('lo51tcfce20q05', 'lo51tcfce20', 5, 'qcm', 'Selon l''auteur, quelle est désormais la vraie question ?', '{"doc":"<p><strong>Jeux vidéo : un art ?</strong></p><p>Longtemps méprisé, le jeu vidéo entre aujourd''hui dans les musées. Certains crient au scandale. Pourtant, un jeu réunit scénario, musique, images et architecture : tous les arts que l''on admire ailleurs. La question n''est plus de savoir si c''est un art, mais de distinguer les œuvres réussies des produits commerciaux.</p>","options":["Réduire le prix des jeux vidéo.","Interdire les jeux vidéo dans les musées.","Distinguer les jeux de qualité des produits commerciaux.","Savoir si le jeu vidéo est un art."]}'::jsonb, '{"answer":2}'::jsonb, '« La question n''est plus de savoir si c''est un art, mais de distinguer les œuvres réussies des produits commerciaux ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-3 #6 Lecture TCF : articles d'opinion, révision (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce21', 'practice', 'Lecture TCF : articles d''opinion, révision', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• culpabiliser (verbe) : làm cho thấy có lỗi\n• rater sa mission : không làm tròn sứ mệnh\n• un investissement : khoản đầu tư\n• l''intéressé : người được nhắc tới\n• démodé (adjectif) : lỗi thời","explications":"• « Il ne s''agit pas de X, mais de Y »: mục đích của tác giả là Y.\n• Bài ôn B2: đọc câu cuối mỗi đoạn trước, ý chính thường nằm ở đó.","isPremium":true,"price":19000,"kyNang":"TCF-CE-3","vong":"chot","thuTu":6}'::jsonb, '2026-11-16T10:00:20.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce21q01', 'lo51tcfce21', 1, 'qcm', 'Quel est l''objectif de l''auteur ?', '{"doc":"<p><strong>Moins d''écrans pour les petits</strong></p><p>Les pédiatres recommandent de ne pas exposer les enfants de moins de trois ans aux écrans. Beaucoup de parents trouvent ce conseil irréaliste. Il ne s''agit pas de culpabiliser, mais d''informer : un écran allumé en permanence réduit les échanges, qui sont essentiels à l''apprentissage du langage.</p>","options":["Interdire les écrans dans toutes les maisons.","Critiquer les pédiatres pour leurs conseils.","Informer les parents sans les culpabiliser.","Vendre des jouets éducatifs aux parents."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả viết « Il ne s''agit pas de culpabiliser, mais d''informer ».'),
  ('lo51tcfce21q02', 'lo51tcfce21', 2, 'qcm', 'Quel argument l''auteur avance-t-il ?', '{"doc":"<p><strong>Les bibliothèques ouvertes le dimanche</strong></p><p>Ouvrir les bibliothèques le dimanche coûte cher en personnel. Mais c''est le seul jour où beaucoup de familles et de travailleurs peuvent s''y rendre. Une bibliothèque fermée quand le public est libre rate sa mission.</p>","options":["Le dimanche, le public a enfin du temps libre.","Ouvrir le dimanche ne coûte presque rien.","Les bibliothécaires préfèrent travailler le dimanche.","Les bibliothèques sont vides en semaine."]}'::jsonb, '{"answer":0}'::jsonb, '« c''est le seul jour où beaucoup de familles et de travailleurs peuvent s''y rendre ».'),
  ('lo51tcfce21q03', 'lo51tcfce21', 3, 'qcm', 'Pourquoi l''auteur parle-t-il d''un investissement ?', '{"doc":"<p><strong>Apprendre à cuisiner à l''école</strong></p><p>Les jeunes savent de moins en moins cuisiner et mangent de plus en plus de plats préparés. Des cours de cuisine à l''école leur apprendraient à manger sainement à petit prix. C''est un investissement pour leur santé future, et pour celle du système de soins.</p>","options":["Ces cours rapporteraient de l''argent aux écoles.","Ces cours formeraient de futurs chefs célèbres.","Ces cours protégeraient la santé à long terme.","Ces cours permettraient de vendre des plats préparés."]}'::jsonb, '{"answer":2}'::jsonb, 'Tác giả gọi đó là « un investissement pour leur santé future ».'),
  ('lo51tcfce21q04', 'lo51tcfce21', 4, 'qcm', 'Quelle règle l''auteur propose-t-il ?', '{"doc":"<p><strong>La politesse en ligne</strong></p><p>Sur les réseaux sociaux, on écrit souvent des choses que l''on n''oserait jamais dire en face. L''écran crée une distance qui fait oublier qu''une vraie personne lira le message. Une règle simple suffirait souvent : ne rien écrire qu''on ne pourrait pas dire à voix haute devant l''intéressé.</p>","options":["N''écrire que ce qu''on oserait dire en face.","Lire tous les messages à voix haute avant de les publier.","Toujours écrire sous un faux nom.","Ne plus utiliser du tout les réseaux sociaux."]}'::jsonb, '{"answer":0}'::jsonb, 'Quy tắc: « ne rien écrire qu''on ne pourrait pas dire à voix haute devant l''intéressé ».'),
  ('lo51tcfce21q05', 'lo51tcfce21', 5, 'qcm', 'Selon l''auteur, que permettent les fêtes de quartier ?', '{"doc":"<p><strong>Les fêtes de quartier</strong></p><p>On les croyait démodées. Pourtant, les fêtes de quartier attirent chaque année plus de participants. Dans des villes où l''on ne connaît plus ses voisins, ces moments simples, une table, un repas partagé, recréent un lien que les grandes politiques peinent à construire.</p>","options":["Remplacer les grandes fêtes nationales.","Faire connaître les politiques de la ville.","Recréer des liens entre voisins.","Vendre des produits locaux aux habitants."]}'::jsonb, '{"answer":2}'::jsonb, 'Những dịp này « recréent un lien » giữa những người hàng xóm.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-4 #3 Lecture TCF : essais et réflexions (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce22', 'practice', 'Lecture TCF : essais et réflexions', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• contaminer (verbe) : lây sang, lan sang\n• soustraire à : tách khỏi\n• rentabiliser (verbe) : làm cho sinh lời\n• figé (adjectif) : đóng băng, bất biến\n• méconnaître (verbe) : không hiểu đúng\n• la justesse : sự đúng đắn","explications":"• « Ce n''était pas X, mais Y »: điều được hỏi là Y.\n• Câu « La formule est facile, mais… »: nhận xét của tác giả là phần sau « mais ».","isPremium":true,"price":19000,"kyNang":"TCF-CE-4","vong":"on","thuTu":3}'::jsonb, '2026-11-16T10:00:21.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce22q01', 'lo51tcfce22', 1, 'qcm', 'Quel risque l''auteur évoque-t-il ?', '{"doc":"<p>L''éloge de la productivité a fini par contaminer nos loisirs. Nous comptons nos pas, nos pages lues, nos kilomètres parcourus, comme si le temps libre devait lui aussi produire un résultat mesurable. Or le loisir, au sens ancien, désignait précisément le temps soustrait à toute obligation de rendement. À vouloir le rentabiliser, nous risquons de le perdre.</p>","options":["Lire moins de livres qu''avant.","Perdre le sens véritable du temps libre.","Devenir moins productif au travail.","Ne plus avoir de loisirs du tout."]}'::jsonb, '{"answer":1}'::jsonb, 'Tác giả kết: « À vouloir le rentabiliser, nous risquons de le perdre ».'),
  ('lo51tcfce22q02', 'lo51tcfce22', 2, 'qcm', 'Que suggère l''auteur à propos des commémorations ?', '{"doc":"<p>On présente volontiers la mémoire collective comme un héritage figé, transmis de génération en génération. C''est méconnaître son caractère vivant : chaque époque relit le passé à la lumière de ses propres questions. Les commémorations en disent souvent davantage sur ceux qui les organisent que sur les événements qu''elles célèbrent.</p>","options":["Elles intéressent peu les jeunes générations.","Elles devraient être moins nombreuses.","Elles révèlent surtout les préoccupations du présent.","Elles transmettent fidèlement le passé."]}'::jsonb, '{"answer":2}'::jsonb, 'Lễ tưởng niệm « en disent souvent davantage sur ceux qui les organisent ».'),
  ('lo51tcfce22q03', 'lo51tcfce22', 3, 'qcm', 'Que regrette le personnage ?', '{"doc":"<p><em>Extrait d''un roman</em></p><p>Il avait toujours cru que partir serait une libération. Pourtant, dans le train qui l''éloignait de la ville, il ne ressentait qu''une étrange lourdeur. Ce n''était pas la ville qu''il regrettait, mais celui qu''il y avait été, et qu''il savait ne plus jamais pouvoir redevenir.</p>","options":["Son ancien travail en ville.","Une version de lui-même qu''il laisse derrière lui.","La ville où il a vécu longtemps.","Les amis restés dans la ville."]}'::jsonb, '{"answer":1}'::jsonb, '« Ce n''était pas la ville qu''il regrettait, mais celui qu''il y avait été ».'),
  ('lo51tcfce22q04', 'lo51tcfce22', 4, 'qcm', 'Quelle est la position de l''auteur sur la formule citée ?', '{"doc":"<p>La gratuité apparente de nombreux services numériques masque un échange inégal. Nous ne payons pas avec de l''argent, mais avec notre attention et nos données personnelles, dont la valeur nous échappe. Lorsque le produit est gratuit, disait-on, c''est que le produit, c''est vous. La formule est facile, mais elle n''a rien perdu de sa justesse.</p>","options":["Elle est fausse et trop simpliste.","Elle ne concerne que les réseaux sociaux.","Elle exagère la valeur des données personnelles.","Elle reste juste malgré sa simplicité."]}'::jsonb, '{"answer":3}'::jsonb, 'Tác giả viết « La formule est facile, mais elle n''a rien perdu de sa justesse ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-4 #4 Lecture TCF : sciences et société (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce23', 'practice', 'Lecture TCF : sciences et société', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• réfuter (verbe) : bác bỏ\n• provisoire (adjectif) : tạm thời\n• flatter (verbe) : chiều theo, vuốt ve\n• l''espérance de vie : tuổi thọ trung bình\n• un effet pervers : tác dụng ngược\n• dispenser de : miễn cho khỏi","explications":"• Câu hỏi giải thích một cụm từ: tìm cụm đối lập với nó trong cùng câu.\n• « Il est tentant de croire… » mở đầu một ý mà tác giả sắp bác.","isPremium":true,"price":19000,"kyNang":"TCF-CE-4","vong":"on","thuTu":4}'::jsonb, '2026-11-16T10:00:22.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce23q01', 'lo51tcfce23', 1, 'qcm', 'Selon l''auteur, qu''est-ce qui fait la force de la science ?', '{"doc":"<p>La science ne progresse pas en accumulant des certitudes, mais en réfutant des hypothèses. Un résultat scientifique est toujours provisoire : il vaut tant qu''aucune observation ne vient le contredire. C''est précisément ce caractère révisable, que ses adversaires prennent pour une faiblesse, qui fait sa force.</p>","options":["Le fait que ses résultats puissent être révisés.","La rapidité de ses découvertes.","L''accumulation de certitudes définitives.","Le refus de toute contradiction."]}'::jsonb, '{"answer":0}'::jsonb, 'Tác giả nói chính tính « révisable » của khoa học « fait sa force ».'),
  ('lo51tcfce23q02', 'lo51tcfce23', 2, 'qcm', 'Pourquoi l''auteur critique-t-il le mythe du génie solitaire ?', '{"doc":"<p>On attribue volontiers les grandes découvertes à des génies solitaires. L''histoire réelle est plus collective : chaque avancée s''appuie sur les travaux de dizaines de chercheurs oubliés. Le mythe du génie isolé flatte notre goût des héros, mais il décourage ceux qui croient qu''il faut un talent exceptionnel pour contribuer au savoir.</p>","options":["Il coûte cher aux universités.","Il rend les chercheurs trop célèbres.","Il décourage ceux qui pourraient contribuer à la recherche.","Il ne correspond à aucune découverte réelle."]}'::jsonb, '{"answer":2}'::jsonb, 'Huyền thoại này « décourage ceux qui croient qu''il faut un talent exceptionnel pour contribuer au savoir ».'),
  ('lo51tcfce23q03', 'lo51tcfce23', 3, 'qcm', 'Que signifie « ajouter de la vie aux années » ?', '{"doc":"<p>La médecine a fait reculer la mort à un point que nos ancêtres n''auraient pas imaginé. Mais vivre plus longtemps ne signifie pas toujours vivre mieux. La véritable question n''est plus seulement d''ajouter des années à la vie, mais d''ajouter de la vie aux années.</p>","options":["Travailler plus longtemps avant la retraite.","Avoir plus d''enfants plus tard.","Allonger encore l''espérance de vie.","Améliorer la qualité des années vécues."]}'::jsonb, '{"answer":3}'::jsonb, 'Đối lập với « ajouter des années à la vie »: không chỉ sống lâu mà còn « vivre mieux ».'),
  ('lo51tcfce23q04', 'lo51tcfce23', 4, 'qcm', 'Quel « effet pervers » l''auteur dénonce-t-il ?', '{"doc":"<p>Il est tentant de croire que la technologie résoudra seule la crise climatique. Cette confiance a un effet pervers : elle nous dispense de remettre en question nos modes de vie. Or aucune innovation ne compensera entièrement une consommation qui ne cesse de croître.</p>","options":["On refuse toutes les innovations.","On consomme moins d''énergie qu''avant.","On investit trop dans la technologie.","On évite de changer ses habitudes."]}'::jsonb, '{"answer":3}'::jsonb, 'Niềm tin đó « nous dispense de remettre en question nos modes de vie ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-4 #5 Lecture TCF : implicite et nuances, révision (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce24', 'practice', 'Lecture TCF : implicite et nuances, révision', 'TCF', array['Lecture']::text[], 'practice', null, null, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''abondance (nom féminin) : sự dồi dào\n• l''emporter sur : thắng thế\n• l''épaisseur d''une vie : bề dày một đời người\n• se heurter à : vấp phải\n• légitime (adjectif) : chính đáng\n• d''autant plus… que : càng… khi","explications":"• « d''autant plus… que… » nối hai vế tỉ lệ: càng A thì càng B.\n• Đoạn văn chương: câu trả lời thường là ý được « mais » đặt sau « Le plus difficile n''était pas… ».","isPremium":true,"price":19000,"kyNang":"TCF-CE-4","vong":"chot","thuTu":5}'::jsonb, '2026-11-16T10:00:23.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce24q01', 'lo51tcfce24', 1, 'qcm', 'Quel paradoxe l''auteur souligne-t-il ?', '{"doc":"<p>Nous vivons, dit-on, à l''ère de la communication. Jamais pourtant il n''a été aussi difficile de se faire entendre : chacun parle, peu écoutent. L''abondance des messages produit moins le dialogue qu''un vaste bruit de fond, où la parole la plus forte l''emporte sur la plus juste.</p>","options":["On communique moins qu''autrefois.","Les messages sont de plus en plus justes.","Plus on communique, moins on s''écoute.","Le silence est devenu impossible en ville."]}'::jsonb, '{"answer":2}'::jsonb, '« Jamais pourtant il n''a été aussi difficile de se faire entendre : chacun parle, peu écoutent ».'),
  ('lo51tcfce24q02', 'lo51tcfce24', 2, 'qcm', 'Qu''est-ce qui est le plus difficile pour le personnage ?', '{"doc":"<p><em>Extrait d''un roman</em></p><p>Elle rangeait la maison de sa mère depuis une semaine. Chaque objet lui demandait une décision : garder ou donner. Le plus difficile n''était pas de se séparer des choses précieuses, mais des choses sans valeur, ces petits riens qui avaient fait, sans qu''elle s''en aperçoive, toute l''épaisseur d''une vie.</p>","options":["Vendre les objets les plus précieux.","Trouver le temps de ranger la maison.","Décider où habiter après la maison.","Se séparer des objets ordinaires du quotidien."]}'::jsonb, '{"answer":3}'::jsonb, '« Le plus difficile n''était pas de se séparer des choses précieuses, mais des choses sans valeur ».'),
  ('lo51tcfce24q03', 'lo51tcfce24', 3, 'qcm', 'Selon l''auteur, pourquoi les réformes échouent-elles parfois ?', '{"doc":"<p>Toute réforme se heurte à une résistance qu''il serait trop simple d''attribuer à l''égoïsme. Changer, c''est renoncer à des habitudes qui, même imparfaites, procurent une sécurité. Une réforme qui ignore cette peur légitime se condamne à l''échec, quelle que soit la qualité de ses intentions.</p>","options":["Elles sont trop rapides à mettre en place.","Les citoyens sont trop égoïstes.","Elles ne tiennent pas compte de la peur du changement.","Leurs intentions sont mauvaises."]}'::jsonb, '{"answer":2}'::jsonb, 'Cải cách « qui ignore cette peur légitime se condamne à l''échec ».'),
  ('lo51tcfce24q04', 'lo51tcfce24', 4, 'qcm', 'Qu''est-ce qu''une bonne traduction selon l''auteur ?', '{"doc":"<p>La traduction a ceci de paradoxal qu''elle est d''autant plus réussie qu''elle se fait oublier. Le lecteur d''un roman traduit croit lire l''auteur ; il lit en réalité un second écrivain, dont tout le talent consiste à rester invisible.</p>","options":["Une traduction que le lecteur ne remarque pas.","Une traduction qui suit chaque mot de l''original.","Une traduction signée par un écrivain célèbre.","Une traduction qui améliore le texte original."]}'::jsonb, '{"answer":0}'::jsonb, 'Bản dịch « est d''autant plus réussie qu''elle se fait oublier ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-5 #2 Lecture TCF : mini-test 2 (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce25', 'practice', 'Lecture TCF : mini-test 2', 'TCF', array['Lecture']::text[], 'practice', null, 18, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un tarif réduit : giá giảm\n• reporté (participe) : bị hoãn\n• valable (adjectif) : còn hiệu lực\n• l''âme sœur : người tri kỷ\n• inconscient (adjectif) : không ý thức\n• complice (adjectif) : đồng loã, hiểu ý","explications":"• Chia 18 phút: khoảng 1 phút cho mỗi câu A1 đến B1, 2 phút cho mỗi câu B2 đến C2.\n• Câu C1, C2 thường có cấu trúc « ne… pas X, mais Y » hoặc « au contraire »: tìm Y.","isPremium":true,"price":19000,"kyNang":"TCF-CE-5","vong":"chot","thuTu":2}'::jsonb, '2026-11-16T10:00:24.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce25q01', 'lo51tcfce25', 1, 'qcm', 'Quel jour les billets sont-ils moins chers ?', '{"doc":"<p><strong>CINÉMA REX</strong></p><p>Séances : 14 h, 17 h, 20 h.</p><p>Mardi : tarif réduit pour tous.</p>","options":["Tous les jours à 14 h.","Le lundi.","Le mardi.","Le dimanche."]}'::jsonb, '{"answer":2}'::jsonb, 'Biển ghi « Mardi : tarif réduit pour tous ».'),
  ('lo51tcfce25q02', 'lo51tcfce25', 2, 'qcm', 'Pourquoi Paul ne va-t-il pas au football ?', '{"doc":"<p>Salut Max,</p><p>Je suis malade, je ne viens pas au foot ce soir. Désolé !</p><p>Paul</p>","options":["Il a un autre match.","Il travaille ce soir.","Il est malade.","Il a oublié la date."]}'::jsonb, '{"answer":2}'::jsonb, 'Paul viết « Je suis malade ».'),
  ('lo51tcfce25q03', 'lo51tcfce25', 3, 'qcm', 'Qu''est-ce qui change à partir du 1er avril ?', '{"doc":"<p><strong>Supermarché Bio Vert</strong></p><p>Nouveaux horaires à partir du 1er avril : ouvert le dimanche matin de 9 h à 13 h.</p>","options":["Le magasin ouvre plus tôt en semaine.","Le magasin ouvre le dimanche matin.","Le magasin change d''adresse.","Le magasin ferme le dimanche."]}'::jsonb, '{"answer":1}'::jsonb, 'Từ 1/4 « ouvert le dimanche matin de 9 h à 13 h ».'),
  ('lo51tcfce25q04', 'lo51tcfce25', 4, 'qcm', 'Quelle information donne le garage ?', '{"doc":"<p>Bonjour Madame Blanc,</p><p>Votre voiture sera prête vendredi. Le montant de la réparation est de 180 €. Paiement possible par carte.</p><p>Garage du Lac</p>","options":["Le prix de la réparation.","L''adresse d''un autre garage.","Le jour où la voiture sera vendue.","Le nom du mécanicien qui répare."]}'::jsonb, '{"answer":0}'::jsonb, 'Garage báo « Le montant de la réparation est de 180 € ».'),
  ('lo51tcfce25q05', 'lo51tcfce25', 5, 'qcm', 'Que doivent faire les parents qui ont déjà signé l''autorisation ?', '{"doc":"<p><strong>Objet :</strong> sortie scolaire</p><p>Chers parents, la sortie au musée prévue le 12 mai est reportée au 19 mai à cause d''une grève des transports. Les autorisations déjà signées restent valables.</p>","options":["Rien de plus.","Accompagner leurs enfants au musée.","Signer une nouvelle autorisation.","Payer une nouvelle participation."]}'::jsonb, '{"answer":0}'::jsonb, '« Les autorisations déjà signées restent valables »: không cần làm gì thêm.'),
  ('lo51tcfce25q06', 'lo51tcfce25', 6, 'qcm', 'Qu''est-ce qui est payant ?', '{"doc":"<p><strong>Atelier vélo</strong></p><p>Chaque samedi, des bénévoles vous apprennent à réparer vous-même votre vélo. Les outils sont prêtés. Seules les pièces neuves sont payantes.</p>","options":["Les pièces neuves.","L''aide des bénévoles.","Les outils prêtés.","L''entrée de l''atelier."]}'::jsonb, '{"answer":0}'::jsonb, '« Seules les pièces neuves sont payantes ».'),
  ('lo51tcfce25q07', 'lo51tcfce25', 7, 'qcm', 'Quel risque l''auteur évoque-t-il ?', '{"doc":"<p>Les applications de rencontre promettent de trouver l''âme sœur en quelques clics. Elles ont surtout transformé l''amour en marché, où chacun compare des profils comme on compare des produits. Le risque n''est pas de ne trouver personne, mais de croire qu''il existe toujours mieux ailleurs.</p>","options":["Dépenser trop d''argent sur les applications.","Se faire voler ses données personnelles.","Penser qu''on peut toujours trouver mieux.","Ne rencontrer personne en ligne."]}'::jsonb, '{"answer":2}'::jsonb, '« Le risque n''est pas de ne trouver personne, mais de croire qu''il existe toujours mieux ailleurs ».'),
  ('lo51tcfce25q08', 'lo51tcfce25', 8, 'qcm', 'Quelle condition l''auteur pose-t-il ?', '{"doc":"<p>Les villes plantent des arbres pour lutter contre la chaleur. L''idée est bonne, à condition de choisir des espèces adaptées au climat futur et de les arroser les premières années. Un arbre mal choisi ou abandonné meurt vite, et l''argent public avec lui.</p>","options":["Laisser les habitants choisir les arbres.","Ne planter que des arbres fruitiers.","Planter le plus d''arbres possible.","Choisir les bons arbres et les entretenir."]}'::jsonb, '{"answer":3}'::jsonb, '« à condition de choisir des espèces adaptées au climat futur et de les arroser les premières années ».'),
  ('lo51tcfce25q09', 'lo51tcfce25', 9, 'qcm', 'Comment l''auteur définit-il le courage ?', '{"doc":"<p>On confond souvent le courage avec l''absence de peur. Le courage est au contraire la capacité d''agir malgré la peur. Celui qui n''a peur de rien n''est pas courageux : il est simplement inconscient du danger.</p>","options":["Ignorer le danger.","Agir en ayant peur.","Ne jamais avoir peur.","Éviter les situations dangereuses."]}'::jsonb, '{"answer":1}'::jsonb, '« Le courage est au contraire la capacité d''agir malgré la peur ».'),
  ('lo51tcfce25q10', 'lo51tcfce25', 10, 'qcm', 'Pourquoi le personnage comprend-il que c''est fini ?', '{"doc":"<p><em>Extrait d''un roman</em></p><p>Il relut la lettre trois fois. Les mots étaient aimables, presque chaleureux. C''est justement cette politesse soignée qui lui fit comprendre que tout était fini.</p>","options":["La lettre arrive trop tard.","La lettre est écrite avec colère.","Le ton de la lettre est trop poli.","La lettre annonce clairement une rupture."]}'::jsonb, '{"answer":2}'::jsonb, '« C''est justement cette politesse soignée qui lui fit comprendre que tout était fini ».'),
  ('lo51tcfce25q11', 'lo51tcfce25', 11, 'qcm', 'Quelle idée l''auteur défend-il ?', '{"doc":"<p>La tolérance ne consiste pas à tout accepter. Une tolérance sans limites finirait par tolérer ceux qui veulent la détruire. C''est donc par fidélité à elle-même qu''une société tolérante doit parfois savoir dire non.</p>","options":["La tolérance suppose parfois des refus.","La tolérance doit être imposée par la loi.","La tolérance consiste à tout accepter.","La tolérance est une valeur dépassée."]}'::jsonb, '{"answer":0}'::jsonb, 'Một xã hội khoan dung « doit parfois savoir dire non ».'),
  ('lo51tcfce25q12', 'lo51tcfce25', 12, 'qcm', 'Que faut-il pour que l''ironie fonctionne ?', '{"doc":"<p>L''ironie est l''arme de ceux qui ne peuvent pas dire ouvertement ce qu''ils pensent. Mais elle exige un lecteur complice : celui qui ne saisit pas le double sens prend la critique pour un compliment.</p>","options":["Un sujet léger et amusant.","Un auteur célèbre et respecté.","Un lecteur capable de saisir le double sens.","Une critique dite ouvertement."]}'::jsonb, '{"answer":2}'::jsonb, 'Mỉa mai « exige un lecteur complice », người hiểu được « le double sens ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-CE-5 #3 Lecture TCF : mini-test 3 (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo51tcfce26', 'practice', 'Lecture TCF : mini-test 3', 'TCF', array['Lecture']::text[], 'practice', null, 18, '<p><strong>Comme au TCF :</strong> chaque question a son propre document. Lisez d''abord la question, puis cherchez la réponse dans le document et choisissez A, B, C ou D.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une serviette : khăn tắm\n• héberger (verbe) : cho ở nhờ\n• une tutrice : người hướng dẫn (nữ)\n• un engrais : phân bón\n• le profane : người ngoại đạo, không chuyên\n• un décor : phông cảnh","explications":"• Đọc câu hỏi trước rồi mới đọc tài liệu: tiết kiệm thời gian cho các văn bản dài ở cuối.\n• Hình ảnh ẩn dụ (« un décor », « les acteurs ») ở C2: dịch hình ảnh về nghĩa thật trước khi chọn.","isPremium":true,"price":19000,"kyNang":"TCF-CE-5","vong":"chot","thuTu":3}'::jsonb, '2026-11-16T10:00:25.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo51tcfce26q01', 'lo51tcfce26', 1, 'qcm', 'Quand faut-il réserver ?', '{"doc":"<p><strong>RESTAURANT CHEZ ANNA</strong></p><p>Fermé le lundi.</p><p>Réservation conseillée le week-end.</p>","options":["Le week-end.","Jamais.","Le lundi.","Tous les soirs."]}'::jsonb, '{"answer":0}'::jsonb, 'Biển ghi « Réservation conseillée le week-end ».'),
  ('lo51tcfce26q02', 'lo51tcfce26', 2, 'qcm', 'Que doit apporter Lisa ?', '{"doc":"<p>Coucou Lisa,</p><p>Rendez-vous à 15 h devant la piscine. N''oublie pas ta serviette !</p><p>Emma</p>","options":["Une serviette.","Un maillot de bain neuf.","Un goûter.","De l''argent pour l''entrée."]}'::jsonb, '{"answer":0}'::jsonb, 'Emma dặn « N''oublie pas ta serviette ! ».'),
  ('lo51tcfce26q03', 'lo51tcfce26', 3, 'qcm', 'Comment les voyageurs de 8 h 10 vont-ils voyager ?', '{"doc":"<p><strong>Information voyageurs</strong></p><p>En raison de travaux, le train de 8 h 10 est remplacé par un bus. Départ devant la gare.</p>","options":["En train, avec du retard.","En taxi gratuit.","En bus.","Ils ne peuvent pas partir."]}'::jsonb, '{"answer":2}'::jsonb, 'Tàu 8 h 10 « est remplacé par un bus ».'),
  ('lo51tcfce26q04', 'lo51tcfce26', 4, 'qcm', 'Qu''est-ce qui manque au dossier ?', '{"doc":"<p>Bonjour Monsieur Lopez,</p><p>Nous avons bien reçu votre dossier d''inscription. Il manque une photo d''identité. Merci de l''envoyer avant le 15 septembre.</p><p>Le secrétariat</p>","options":["Une signature.","Le paiement de l''inscription.","Une photo.","Un justificatif de domicile."]}'::jsonb, '{"answer":2}'::jsonb, 'Thư ký báo « Il manque une photo d''identité ».'),
  ('lo51tcfce26q05', 'lo51tcfce26', 5, 'qcm', 'Que doit faire un étudiant qui veut faire dormir un ami chez lui ?', '{"doc":"<p><strong>Résidence étudiante</strong></p><p>Pour des raisons de sécurité, les visiteurs doivent quitter la résidence avant 23 h. Les étudiants qui souhaitent héberger un proche pour la nuit doivent en faire la demande à l''accueil.</p>","options":["Demander une autorisation à l''accueil.","Prévenir ses voisins de couloir.","Faire partir son ami avant 23 h.","Payer une chambre supplémentaire."]}'::jsonb, '{"answer":0}'::jsonb, 'Muốn cho người quen ngủ lại thì « doivent en faire la demande à l''accueil ».'),
  ('lo51tcfce26q06', 'lo51tcfce26', 6, 'qcm', 'Que décide Yanis ?', '{"doc":"<p>Salut Karim,</p><p>Le stage s''est bien passé. J''ai appris beaucoup, surtout grâce à ma tutrice, très patiente. Ils m''ont proposé un contrat à partir de septembre, mais je préfère d''abord finir mes études.</p><p>Yanis</p>","options":["Chercher un autre stage.","Arrêter ses études pour travailler.","Terminer ses études avant de travailler.","Accepter le contrat dès septembre."]}'::jsonb, '{"answer":2}'::jsonb, 'Yanis viết « je préfère d''abord finir mes études ».'),
  ('lo51tcfce26q07', 'lo51tcfce26', 7, 'qcm', 'Que conclut l''auteur ?', '{"doc":"<p>La gratuité des musées pour les jeunes a augmenté leur fréquentation. Mais les jeunes qui viennent sont surtout ceux dont les parents fréquentaient déjà les musées. Supprimer le prix du billet ne suffit donc pas : il faut aussi aller chercher les publics éloignés de la culture.</p>","options":["Les musées devraient redevenir payants.","La gratuité a fait baisser la fréquentation.","La gratuité ne suffit pas à attirer tous les publics.","Les jeunes ne s''intéressent pas aux musées."]}'::jsonb, '{"answer":2}'::jsonb, '« Supprimer le prix du billet ne suffit donc pas ».'),
  ('lo51tcfce26q08', 'lo51tcfce26', 8, 'qcm', 'Selon l''auteur, quel est le vrai problème ?', '{"doc":"<p>On critique souvent les jeunes pour leur usage du téléphone. On oublie qu''ils l''utilisent aussi pour s''informer, apprendre et s''engager. Le problème n''est pas l''outil, mais l''absence d''éducation à son usage.</p>","options":["Le temps passé à s''informer.","Le téléphone lui-même.","Le manque d''éducation à l''usage du téléphone.","Le prix des téléphones."]}'::jsonb, '{"answer":2}'::jsonb, '« Le problème n''est pas l''outil, mais l''absence d''éducation à son usage ».'),
  ('lo51tcfce26q09', 'lo51tcfce26', 9, 'qcm', 'Que faut-il faire pour juger un progrès ?', '{"doc":"<p>Le progrès a longtemps été pensé comme une ligne droite. Nous savons aujourd''hui qu''il peut avoir des effets contraires à ses promesses : la voiture qui libère encombre, l''engrais qui nourrit pollue. Juger un progrès exige d''en mesurer aussi les conséquences imprévues.</p>","options":["Prendre en compte ses effets inattendus.","Mesurer seulement ses promesses.","Attendre plusieurs siècles.","Refuser toute nouvelle technologie."]}'::jsonb, '{"answer":0}'::jsonb, '« Juger un progrès exige d''en mesurer aussi les conséquences imprévues ».'),
  ('lo51tcfce26q10', 'lo51tcfce26', 10, 'qcm', 'Quel sentiment domine chez le personnage ?', '{"doc":"<p><em>Extrait d''un roman</em></p><p>Il avait gagné le prix qu''il attendait depuis vingt ans. Sur la scène, sous les applaudissements, il ne pensait qu''à une chose : son père n''était plus là pour le voir.</p>","options":["La peur de parler en public.","Une joie sans mélange.","Une tristesse liée à l''absence de son père.","La colère contre le jury."]}'::jsonb, '{"answer":2}'::jsonb, 'Giữa tiếng vỗ tay, ông chỉ nghĩ « son père n''était plus là pour le voir ».'),
  ('lo51tcfce26q11', 'lo51tcfce26', 11, 'qcm', 'Selon l''auteur, qu''est-ce qui distingue l''expert ?', '{"doc":"<p>L''expert et le profane ne diffèrent pas seulement par la quantité de savoir, mais par la conscience de ses limites. Le profane voit des réponses simples là où l''expert perçoit des questions complexes.</p>","options":["Il refuse les questions complexes.","Il connaît les limites de son savoir.","Il connaît plus de réponses simples.","Il parle plus souvent en public."]}'::jsonb, '{"answer":1}'::jsonb, 'Khác biệt nằm ở « la conscience de ses limites ».'),
  ('lo51tcfce26q12', 'lo51tcfce26', 12, 'qcm', 'Que reproche l''auteur à une certaine protection du patrimoine ?', '{"doc":"<p>Une ville ne se résume pas à ses monuments. Elle est faite d''usages, de trajets quotidiens, de rencontres imprévues. Protéger son patrimoine sans protéger ceux qui y vivent, c''est conserver un décor en chassant les acteurs.</p>","options":["Elle détruit les monuments anciens.","Elle oublie les habitants.","Elle coûte trop cher aux villes.","Elle attire trop peu de touristes."]}'::jsonb, '{"answer":1}'::jsonb, 'Bảo tồn mà không bảo vệ cư dân là « conserver un décor en chassant les acteurs ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
